-- Canonical identity facts, part of the complete schema 11 baseline.
CREATE TABLE organization_labels(id BIGINT PRIMARY KEY REFERENCES records(id) ON DELETE CASCADE,name TEXT NOT NULL,is_active BIGINT NOT NULL CHECK(is_active IN (0,1)));
CREATE TABLE persons(id BIGINT PRIMARY KEY REFERENCES records(id) ON DELETE CASCADE,full_name TEXT NOT NULL,employee_number TEXT NOT NULL,status TEXT NOT NULL,employment_type TEXT NOT NULL,hire_date TEXT NOT NULL,probation_ends_on TEXT,contract_ends_on TEXT);
CREATE TABLE accounts(id BIGINT PRIMARY KEY REFERENCES records(id) ON DELETE CASCADE,username TEXT NOT NULL UNIQUE,full_name TEXT NOT NULL,role_code TEXT NOT NULL,is_active BIGINT NOT NULL CHECK(is_active IN (0,1)),template_id BIGINT REFERENCES permission_schemes(id),use_role_defaults BIGINT NOT NULL CHECK(use_role_defaults IN (0,1)),source_mode TEXT NOT NULL CHECK(source_mode IN ('Independent','Template')));
CREATE TABLE account_grants(account_id BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,resource_key TEXT NOT NULL,action TEXT NOT NULL,data_scope TEXT NOT NULL CHECK(data_scope IN ('own','department','company','all')),PRIMARY KEY(account_id,resource_key,action));
CREATE TABLE identity_projection(id BIGINT PRIMARY KEY REFERENCES records(id) ON DELETE CASCADE,body JSONB NOT NULL);
CREATE VIEW identity_facts AS SELECT r.id,r.kind,r.identity,r.version,r.owner_id,r.company,r.department,r.search_text,
CASE r.kind WHEN 'companies' THEN jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(r.body,'{code}',COALESCE(to_jsonb(u.code),'null'::jsonb),true),'{name}',COALESCE(to_jsonb(l.name),'null'::jsonb),true),'{isActive}',COALESCE(to_jsonb((l.is_active=1)),'null'::jsonb),true),'{parentCompanyCode}',COALESCE(to_jsonb(COALESCE((SELECT code FROM organization_units a WHERE a.id=u.parent_id),'')),'null'::jsonb),true),'{unitKind}',COALESCE(to_jsonb(u.unit_kind),'null'::jsonb),true),'{executiveAppointmentId}',COALESCE(to_jsonb((SELECT appointment_id FROM organization_duties d WHERE d.organization_id=r.id AND d.duty_kind='Primary')),'null'::jsonb),true),'{additionalLeaders}',COALESCE(to_jsonb(COALESCE((SELECT jsonb_agg(value) FROM (SELECT jsonb_build_object('employeeId',(SELECT person_id FROM personnel_memberships a WHERE a.id=d.appointment_id),'appointmentId',d.appointment_id,'workflowKinds',d.workflow_kinds) AS value FROM organization_duties d WHERE d.organization_id=r.id AND d.duty_kind='Delegate' ORDER BY d.appointment_id) q),'[]'::jsonb)),'null'::jsonb),true) WHEN 'departments' THEN jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(r.body,'{code}',COALESCE(to_jsonb(dep.code),'null'::jsonb),true),'{name}',COALESCE(to_jsonb(l.name),'null'::jsonb),true),'{isActive}',COALESCE(to_jsonb((l.is_active=1)),'null'::jsonb),true),'{companyCode}',COALESCE(to_jsonb((SELECT code FROM organization_units a WHERE a.id=dep.unit_id)),'null'::jsonb),true),'{parentCode}',COALESCE(to_jsonb(COALESCE((SELECT code FROM organization_departments a WHERE a.id=dep.parent_id),'')),'null'::jsonb),true),'{managerAppointmentId}',COALESCE(to_jsonb((SELECT appointment_id FROM organization_duties d WHERE d.organization_id=r.id AND d.duty_kind='Primary')),'null'::jsonb),true),'{additionalLeaders}',COALESCE(to_jsonb(COALESCE((SELECT jsonb_agg(value) FROM (SELECT jsonb_build_object('employeeId',(SELECT person_id FROM personnel_memberships a WHERE a.id=d.appointment_id),'appointmentId',d.appointment_id,'workflowKinds',d.workflow_kinds) AS value FROM organization_duties d WHERE d.organization_id=r.id AND d.duty_kind='Delegate' ORDER BY d.appointment_id) q),'[]'::jsonb)),'null'::jsonb),true) WHEN 'people' THEN jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(r.body,'{fullName}',COALESCE(to_jsonb(p.full_name),'null'::jsonb),true),'{profile,fullName}',COALESCE(to_jsonb(p.full_name),'null'::jsonb),true),'{employeeNumber}',COALESCE(to_jsonb(p.employee_number),'null'::jsonb),true),'{status}',COALESCE(to_jsonb(p.status),'null'::jsonb),true),'{employmentType}',COALESCE(to_jsonb(p.employment_type),'null'::jsonb),true),'{hireDate}',COALESCE(to_jsonb(p.hire_date),'null'::jsonb),true),'{probationEndsOn}',COALESCE(to_jsonb(p.probation_ends_on),'null'::jsonb),true),'{contractEndsOn}',COALESCE(to_jsonb(p.contract_ends_on),'null'::jsonb),true),'{jobTitle}',COALESCE(to_jsonb((SELECT job_title FROM personnel_memberships m WHERE m.person_id=r.id AND m.is_primary=1)),'null'::jsonb),true),'{organization}',COALESCE(to_jsonb(jsonb_build_object('primaryAssignmentId',(SELECT id FROM personnel_memberships m WHERE m.person_id=r.id AND m.is_primary=1),'primaryStartsOn',(SELECT starts_on FROM personnel_memberships m WHERE m.person_id=r.id AND m.is_primary=1),'managerAssignmentId',(SELECT manager_appointment_id FROM reporting_relations f WHERE f.appointment_id=(SELECT id FROM personnel_memberships m WHERE m.person_id=r.id AND m.is_primary=1) AND f.relation_type='Line'),'functionalManagerAssignmentIds',COALESCE((SELECT jsonb_agg(value) FROM (SELECT f.manager_appointment_id AS value FROM reporting_relations f WHERE f.appointment_id=(SELECT id FROM personnel_memberships m WHERE m.person_id=r.id AND m.is_primary=1) AND f.relation_type='Functional' ORDER BY f.manager_appointment_id) q),'[]'::jsonb),'managerEmployeeId',(SELECT person_id FROM personnel_memberships m WHERE m.id=(SELECT manager_appointment_id FROM reporting_relations f WHERE f.appointment_id=(SELECT id FROM personnel_memberships m WHERE m.person_id=r.id AND m.is_primary=1) AND f.relation_type='Line')),'functionalManagerEmployeeIds',COALESCE((SELECT jsonb_agg(value) FROM (SELECT m.person_id AS value FROM reporting_relations f JOIN personnel_memberships m ON m.id=f.manager_appointment_id WHERE f.appointment_id=(SELECT id FROM personnel_memberships m WHERE m.person_id=r.id AND m.is_primary=1) AND f.relation_type='Functional' ORDER BY m.person_id) q),'[]'::jsonb),'additionalAssignments',COALESCE((SELECT jsonb_agg(value) FROM (SELECT jsonb_build_object('id',m.id,'companyCode',m.company,'departmentId',m.department,'jobTitle',m.job_title,'startsOn',m.starts_on,'endsOn',m.ends_on,'managerAssignmentId',(SELECT manager_appointment_id FROM reporting_relations f WHERE f.appointment_id=m.id AND f.relation_type='Line'),'functionalManagerAssignmentIds',COALESCE((SELECT jsonb_agg(f.manager_appointment_id ORDER BY f.manager_appointment_id) FROM reporting_relations f WHERE f.appointment_id=m.id AND f.relation_type='Functional'),'[]'::jsonb),'managerEmployeeId',(SELECT person_id FROM personnel_memberships a WHERE a.id=(SELECT manager_appointment_id FROM reporting_relations f WHERE f.appointment_id=m.id AND f.relation_type='Line')),'functionalManagerEmployeeIds',COALESCE((SELECT jsonb_agg(value) FROM (SELECT a.person_id AS value FROM reporting_relations f JOIN personnel_memberships a ON a.id=f.manager_appointment_id WHERE f.appointment_id=m.id AND f.relation_type='Functional' ORDER BY a.person_id) q),'[]'::jsonb)) AS value FROM personnel_memberships m WHERE m.person_id=r.id AND m.is_primary=0 ORDER BY m.starts_on,m.id) q),'[]'::jsonb))),'null'::jsonb),true),'{account}',COALESCE(to_jsonb(CASE WHEN EXISTS(SELECT 1 FROM personnel_accounts a WHERE a.person_id=r.id) THEN jsonb_build_object('id',(SELECT user_id FROM personnel_accounts a WHERE a.person_id=r.id)) ELSE NULL END),'null'::jsonb),true),'{employee}',COALESCE(to_jsonb(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(COALESCE(NULLIF(r.body->'employee','null'::jsonb),'{}'::jsonb),'{id}',COALESCE(to_jsonb(r.id),'null'::jsonb),true),'{fullName}',COALESCE(to_jsonb(p.full_name),'null'::jsonb),true),'{employeeNumber}',COALESCE(to_jsonb(p.employee_number),'null'::jsonb),true),'{status}',COALESCE(to_jsonb(p.status),'null'::jsonb),true),'{employmentType}',COALESCE(to_jsonb(p.employment_type),'null'::jsonb),true),'{hireDate}',COALESCE(to_jsonb(p.hire_date),'null'::jsonb),true),'{jobTitle}',COALESCE(to_jsonb((SELECT job_title FROM personnel_memberships m WHERE m.person_id=r.id AND m.is_primary=1)),'null'::jsonb),true),'{departmentId}',COALESCE(to_jsonb(r.department),'null'::jsonb),true)),'null'::jsonb),true) WHEN 'users' THEN jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(r.body,'{username}',COALESCE(to_jsonb(a.username),'null'::jsonb),true),'{fullName}',COALESCE(to_jsonb(a.full_name),'null'::jsonb),true),'{role}',COALESCE(to_jsonb(a.role_code),'null'::jsonb),true),'{isActive}',COALESCE(to_jsonb((a.is_active=1)),'null'::jsonb),true),'{permissionTemplateId}',COALESCE(to_jsonb(a.template_id),'null'::jsonb),true),'{permissionGrants}',COALESCE(to_jsonb(CASE WHEN a.source_mode='Independent' THEN COALESCE((SELECT jsonb_agg(value) FROM (SELECT jsonb_build_object('resourceKey',g.resource_key,'action',g.action,'dataScope',g.data_scope) AS value FROM account_grants g WHERE g.account_id=r.id ORDER BY g.resource_key,g.action) q),'[]'::jsonb) ELSE NULL END),'null'::jsonb),true),'{useRoleDefaults}',COALESCE(to_jsonb((a.use_role_defaults=1)),'null'::jsonb),true) WHEN 'permission-templates' THEN jsonb_set(jsonb_set(r.body,'{ownerUnitId}',COALESCE(to_jsonb(s.owner_unit_id),'null'::jsonb),true),'{code}',COALESCE(to_jsonb(s.code),'null'::jsonb),true) WHEN 'unit-access' THEN jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(r.body,'{userId}',COALESCE(to_jsonb(ur.user_id),'null'::jsonb),true),'{companyCode}',COALESCE(to_jsonb((SELECT code FROM organization_units a WHERE a.id=ur.unit_id)),'null'::jsonb),true),'{appointmentId}',COALESCE(to_jsonb(ur.appointment_id),'null'::jsonb),true),'{mode}',COALESCE(to_jsonb(ur.mode),'null'::jsonb),true),'{isActive}',COALESCE(to_jsonb((ur.is_active=1)),'null'::jsonb),true),'{permissionTemplateId}',COALESCE(to_jsonb(ur.template_id),'null'::jsonb),true),'{authorityRoleId}',COALESCE(to_jsonb(ur.authority_role_id),'null'::jsonb),true),'{permissionGrants}',COALESCE(to_jsonb(CASE WHEN ur.source_mode='Independent' THEN COALESCE((SELECT jsonb_agg(value) FROM (SELECT jsonb_build_object('resourceKey',g.resource_key,'action',g.action,'dataScope',g.data_scope) AS value FROM unit_access_grants g WHERE g.role_id=r.id ORDER BY g.resource_key,g.action) q),'[]'::jsonb) ELSE NULL END),'null'::jsonb),true) ELSE r.body END AS body
FROM records r
LEFT JOIN organization_units u ON u.id=r.id
LEFT JOIN organization_departments dep ON dep.id=r.id
LEFT JOIN organization_labels l ON l.id=r.id
LEFT JOIN persons p ON p.id=r.id
LEFT JOIN accounts a ON a.id=r.id
LEFT JOIN permission_schemes s ON s.id=r.id
LEFT JOIN unit_access_roles ur ON ur.id=r.id;
CREATE VIEW identity_rows AS SELECT r.id,r.kind,r.identity,r.version,r.owner_id,r.company,r.department,r.search_text,
CASE WHEN r.kind IN ('companies','departments','people','users','permission-templates','unit-access') THEN p.body ELSE r.body END AS body
FROM records r LEFT JOIN identity_projection p ON p.id=r.id;
